import java.lang.Thread;

class MyDisplay {
    private Thread thread;
    public MyDisplay(Thread t) { this.thread = t; }
    public Thread getThread() { return thread; }
    public static MyDisplay getDefault() { return new MyDisplay(Thread.currentThread()); }
}

public class TestClass {
    public void method() {
        Thread nonUiThread = Thread.currentThread();
        MyDisplay display = MyDisplay.getDefault();

        long id1 = nonUiThread.getId();
        long id2 = display.getThread().getId();

        if (id1 == id2) {
            System.out.println("IDs match");
        }
    }
}

